std::vector<Node> nodes;
nodes.reserve(rt.number_of_vertices());

// First pass: collect all vertices and their incident edges
std::vector<std::vector<RT::Edge>> vertex_edges(rt.number_of_vertices());
for (auto eit = rt.finite_edges_begin(); eit != rt.finite_edges_end(); ++eit) {
    auto v1 = eit->first->vertex(eit->second);
    auto v2 = eit->first->vertex(eit->third);
    vertex_edges[v1->index()].push_back(*eit);
    vertex_edges[v2->index()].push_back(*eit);
}

// Process each vertex
for (auto vit = rt.finite_vertices_begin(); vit != rt.finite_vertices_end(); ++vit) {
    Node node;
    auto point = vit->point();
    node.position = Point(point.x(), point.y(), point.z());

    // Get the weight (potential) from the vertex
    node.mass = vit->weight();

    // Classify node type based on number of incident edges below threshold
    int small_edge_count = 0;
    for (auto const& edge : vertex_edges[vit->index()]) {
        if (is_small_edge(rt, edge, threshold * threshold)) {
            small_edge_count++;
        }
    }
    node.type = type_from_edge_count(small_edge_count);

    // Calculate velocity from incident cells
    Vector velocity(0.0, 0.0, 0.0);
    int cell_count = 0;
    for (auto cit = rt.incident_cells(vit); cit != rt.incident_cells_end(vit); ++cit) {
        if (rt.is_infinite(cit)) continue;
        velocity = velocity + velocity(cit);
        cell_count++;
    }
    if (cell_count > 0) {
        node.velocity = velocity / cell_count;
    } else {
        node.velocity = Vector(0.0, 0.0, 0.0);
    }

    nodes.push_back(node);
}

return nodes;

